// C++ Mangling Example (g++/clang convention)
class Widget {
public:
    void func(int x) {}
    void func(double y) {}
};
// func(int): _ZN6Widget4funcEi
// func(double): _ZN6Widget4funcEd

// C++ Extern "C" (Disables mangling)
extern "C" {
    void c_api_function(int x);
}
// Symbol name: c_api_function

// C++ Templates Mangling
template <typename T>
T add(T a, T b) { return a + b; }
// add<int>: _Z3addIiET_S0_
// add<double>: _Z3addIdET_S0_

// C Function/Variable (No Mangling)
int global_var = 10;
void c_function(void);
// Symbol name: global_var
// Symbol name: c_function

// Weak Symbols (GCC/Clang)
__attribute__((weak)) void default_handler() { /* ... */ }
// Allows user code to override implementation

// Static linkage (Internal visibility)
static int internal_count = 0;
// Symbol not visible outside object file
// (Used for optimization/hiding implementation)
